'use strict';

class TokenBucket {
  constructor({ capacity, refillPerSecond, now } = {}) {
    if (typeof capacity !== 'number' || !isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || !isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }

    this._capacity = capacity;
    this._rate = refillPerSecond; // tokens per ms: rate/1000
    this._nowFn = typeof now === 'function' ? now : () => Date.now();
    const t = this._clockNow();
    if (!isFinite(t) || t < 0) {
      throw new RangeError('now must return a non-negative finite number');
    }

    // Store as a "virtual time + tokens" pair so clock jumps (back or forward)
    // are handled lazily and without ever adding/removing tokens on rewind.
    this._tokens = capacity;
    this._refTime = t;
  }

  _clockNow() {
    return this._nowFn();
  }

  // Advance the bucket to current time (never rewinds).
  _advance() {
    const t = this._clockNow();
    if (!Number.isFinite(t)) throw new RangeError('invalid clock value');
    if (t > this._refTime) {
      const dtMs = t - this._refTime;
      let tokens = this._tokens + (dtMs / 1000) * this._rate;
      if (tokens > this._capacity) tokens = this._capacity;
      this._tokens = tokens;
      this._refTime = t;
    }
    // If clock went backwards or is unchanged, keep previous state: no add/remove.
  }

  available() {
    this._advance();
    return this._tokens;
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
    this._advance();
    if (n > this._tokens) return false;
    const next = this._tokens - n;
    // Avoid tiny negative remainders from float noise.
    this._tokens = next < 0 ? 0 : next;
    return true;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
    this._advance();
    if (this._tokens >= n) return 0;
    if (n > this._capacity || this._rate === 0) return Infinity;

    const deficit = n - this._tokens; // tokens needed
    const msExact = (deficit * 1000) / this._rate;
    return Math.ceil(msExact);
  }
}

module.exports = { TokenBucket };

